using System;
using UnityEngine;

/// <summary>
/// Arcade-style, hand-tuned vehicle controller.
/// Stable and snappy on a flat track, works with keyboard or gamepad sticks.
/// Attach to the root GameObject of the car (must have a Rigidbody and a collider).
/// </summary>
[RequireComponent(typeof(Rigidbody))]
[DisallowMultipleComponent]
public class VehicleController : MonoBehaviour
{
    [Header("Speed (km/h)")]
    public float maxSpeed = 120f;
    public float boostMaxSpeed = 170f;
    public float reverseMaxSpeed = 40f;

    [Header("Engine")]
    [Tooltip("Longitudinal acceleration in m/s^2.")]
    public float accelRate = 18f;
    [Tooltip("Extra acceleration multiplier while boosting.")]
    public float boostAccelMultiplier = 1.7f;
    [Tooltip("Braking deceleration in m/s^2.")]
    public float brakeRate = 30f;
    [Tooltip("Passive slow-down (m/s^2) when no throttle is held.")]
    public float coastDrag = 1.2f;

    [Header("Handling")]
    [Tooltip("Full-lock turn rate in deg/s.")]
    public float steerStrength = 95f;
    [Tooltip("How hard sideways velocity is damped while gripping.")]
    public float lateralGrip = 6f;
    [Tooltip("Lateral damping while drifting (lower = more slide).")]
    public float driftLateralGrip = 0.9f;
    [Tooltip("Steering multiplier while drifting.")]
    public float driftSteerMultiplier = 1.5f;

    [Header("Grounding")]
    public LayerMask groundMask = ~0;
    public float groundRayLength = 1.4f;
    [Tooltip("Extra downward acceleration while grounded, keeps the car planted.")]
    public float downforce = 14f;

    [Header("Boost")]
    [Tooltip("Seconds of boost available when full.")]
    public float boostCapacity = 3f;
    [Tooltip("Capacity burned per second while boosting.")]
    public float boostBurnRate = 1f;
    [Tooltip("Capacity regenerated per second.")]
    public float boostRegenRate = 0.35f;

    [Header("Respawn")]
    [Tooltip("Fall below this height and the car respawns.")]
    public float fallHeight = -12f;
    public KeyCode resetKey = KeyCode.R;

    [Header("Wheel visuals (optional)")]
    public Transform[] frontWheels = new Transform[0];
    public Transform[] rearWheels = new Transform[0];
    [Tooltip("Visual-only wheel radius used to scale spin speed.")]
    public float wheelVisualRadius = 0.34f;
    public float wheelSteerAngle = 28f;
    [Tooltip("Tick on Unity e04208 if your wheels appear to roll backwards.")]
    public bool invertWheelSpin = false;

    [Header("Input (gamepad-friendly)")]
    public string verticalAxis = "Vertical";    // default Unity input
    public string horizontalAxis = "Horizontal";

    // ---- Read-only state for HUD / camera ----
    public float SpeedKmh { get { return speedKmh; } }
    public float Boost01 { get { return boostCapacity > 0f ? boostFuel / boostCapacity : 0f; } }
    public bool IsBoosting { get; private set; }
    public bool IsDrifting { get; private set; }
    public bool IsGrounded { get; private set; }
    public Vector3 Velocity { get { return rb ? rb.velocity : Vector3.zero; } }

    /// <summary>Raised every time the car respawns.</summary>
    public event Action Respawned;

    Rigidbody rb;
    float speedKmh;
    float boostFuel;
    float lastForwardSpeed;
    float visualSpin;
    float steerVisual;
    float rawSteer;
    Vector3 spawnPos;
    Quaternion spawnRot;
    Quaternion[] frontBase = new Quaternion[0];
    Quaternion[] rearBase = new Quaternion[0];

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.mass = 1200f;
        rb.drag = 0f;
        rb.angularDrag = 0.05f;
        rb.interpolation = RigidbodyInterpolation.Interpolate;
        rb.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
        rb.centerOfMass = new Vector3(0f, -0.25f, 0f);

        CacheWheelBases(frontWheels, ref frontBase);
        CacheWheelBases(rearWheels, ref rearBase);
        boostFuel = boostCapacity;
    }

    void Start()
    {
        spawnPos = transform.position;
        spawnRot = transform.rotation;
    }

    static void CacheWheelBases(Transform[] wheels, ref Quaternion[] cache)
    {
        cache = new Quaternion[wheels.Length];
        for (int i = 0; i < wheels.Length; i++)
            cache[i] = wheels[i] ? wheels[i].localRotation : Quaternion.identity;
    }

    bool InputAllowed
    {
        get
        {
            var race = RaceManager.Instance;
            return race == null || race.State != RaceManager.RaceState.Countdown;
        }
    }

    void FixedUpdate()
    {
        float dt = Time.fixedDeltaTime;
        boostFuel = Mathf.Min(boostFuel + boostRegenRate * dt, boostCapacity);

        float vertical = Input.GetAxisRaw(verticalAxis);
        float horizontal = Input.GetAxisRaw(horizontalAxis);
        bool boostHeld = Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift);
        bool driftHeld = Input.GetKey(KeyCode.Space);
        if (!InputAllowed)
            vertical = 0f;

        // --- Ground probe ---
        RaycastHit hit;
        Vector3 origin = transform.position + transform.up * 0.5f;
        bool grounded = Physics.Raycast(origin, -transform.up, out hit,
            0.5f + groundRayLength, groundMask, QueryTriggerInteraction.Ignore);
        IsGrounded = grounded;

        // --- Velocity shaping (arcade: direct, predictable) ---
        Vector3 local = transform.InverseTransformDirection(rb.velocity);
        float forward = local.z;
        float lateral = local.x;

        IsDrifting = grounded && driftHeld && Mathf.Abs(forward) > 1f;
        IsBoosting = false;
        float grip = IsDrifting ? driftLateralGrip : lateralGrip;

        if (grounded)
        {
            // Lateral grip: bleed off sideways speed.
            lateral *= Mathf.Clamp01(1f - grip * dt);

            if (vertical > 0.1f)
            {
                bool wantBoost = boostHeld && boostFuel > 0f && forward > 0.5f;
                IsBoosting = wantBoost;
                if (wantBoost)
                    boostFuel = Mathf.Max(0f, boostFuel - boostBurnRate * dt);

                float rate = accelRate * (IsBoosting ? boostAccelMultiplier : 1f);
                float cap = (IsBoosting ? boostMaxSpeed : maxSpeed) / 3.6f;
                if (forward < cap)
                    forward = Mathf.Min(forward + rate * dt, cap);
            }
            else if (vertical < -0.1f)
            {
                if (forward > 0.2f)
                    forward = Mathf.Max(forward - brakeRate * dt, 0f);
                else
                    forward = Mathf.Max(forward - accelRate * 0.6f * dt, -reverseMaxSpeed / 3.6f);
            }
            else
            {
                float drop = coastDrag * dt * (1f + Mathf.Abs(forward) * 0.08f);
                forward = Mathf.MoveTowards(forward, 0f, drop);
            }

            // Stick to the surface (helps on ramps/kerbs).
            local.y = local.y - downforce * dt;
        }
        else
        {
            // Airborne: mild drag so jumps feel weighty; steering only yaws.
            lateral *= Mathf.Clamp01(1f - 0.2f * dt);
            forward *= Mathf.Clamp01(1f - 0.05f * dt);
        }

        local.x = lateral;
        local.z = forward;
        rb.velocity = transform.TransformDirection(local);
        speedKmh = Mathf.Abs(local.z) * 3.6f;
        lastForwardSpeed = local.z;

        // --- Steering ---
        float speedFactor = Mathf.Clamp01(Mathf.Abs(forward) / 8f);   // need motion to turn
        float steerMul = (IsDrifting ? driftSteerMultiplier : 1f) * (grounded ? 1f : 0.45f);
        float reverseMul = forward < -0.5f ? -1f : 1f;                 // invert while reversing
        float yawDelta = horizontal * steerStrength * speedFactor * steerMul * reverseMul * dt;
        rb.angularVelocity = Vector3.Lerp(rb.angularVelocity, Vector3.zero, grounded ? 0.5f : 0.05f);

        Quaternion desired = rb.rotation * Quaternion.Euler(0f, yawDelta, 0f);
        if (grounded)
        {
            // Align with the surface normal (keeps ramps looking right).
            Quaternion flat = Flatten(hit.normal);
            desired = Quaternion.Slerp(rb.rotation, flat, 1f - Mathf.Exp(-6f * dt))
                      * Quaternion.Euler(0f, yawDelta, 0f);
        }
        rb.MoveRotation(desired);

        // --- Respawn ---
        if (transform.position.y < fallHeight || Input.GetKeyDown(resetKey))
            Respawn();
    }

    /// <summary>Rotation aligned with the given surface normal, preserving heading.</summary>
    Quaternion Flatten(Vector3 up)
    {
        Vector3 fwd = transform.forward;
        Vector3 flattened = fwd - up * Vector3.Dot(fwd, up);
        if (flattened.sqrMagnitude < 0.01f)
            flattened = Vector3.ProjectOnPlane(transform.forward, Vector3.up);
        return Quaternion.LookRotation(flattened.normalized, up);
    }

    public void Respawn()
    {
        transform.position = spawnPos + Vector3.up * 0.05f;
        transform.rotation = spawnRot;
        if (rb)
        {
            rb.velocity = Vector3.zero;
            rb.angularVelocity = Vector3.zero;
        }
        boostFuel = boostCapacity;
        if (Respawned != null) Respawned();
    }

    void Update()
    {
        // --- Wheel visuals ---
        float dt = Time.deltaTime;
        rawSteer = Input.GetAxisRaw(horizontalAxis);
        float spinDir = invertWheelSpin ? 1f : -1f;
        visualSpin += spinDir * (lastForwardSpeed / Mathf.Max(0.05f, wheelVisualRadius)) * dt * Mathf.Rad2Deg;
        if (Mathf.Abs(visualSpin) > 3600000f) visualSpin %= 360f;
        steerVisual = Mathf.Lerp(steerVisual, rawSteer * wheelSteerAngle, 1f - Mathf.Exp(-10f * dt));

        ApplyWheelTransform(frontWheels, frontBase, steerVisual);
        ApplyWheelTransform(rearWheels, rearBase, 0f);
    }

    void ApplyWheelTransform(Transform[] wheels, Quaternion[] bases, float steer)
    {
        if (wheels == null) return;
        for (int i = 0; i < wheels.Length; i++)
        {
            if (!wheels[i] || i >= bases.Length) continue;
            // steer (parent space) * base orientation * spin around the axle
            wheels[i].localRotation =
                Quaternion.Euler(0f, steer, 0f) * bases[i] * Quaternion.Euler(0f, visualSpin, 0f);
        }
    }
}

using UnityEngine;

/// <summary>
/// Smooth chase camera: trails behind the car, leans toward the velocity
/// direction in corners, opens FOV with speed and boost.
/// Add to the Main Camera and assign the vehicle root as target.
/// </summary>
[RequireComponent(typeof(Camera))]
public class CameraFollow : MonoBehaviour
{
    public Transform target;
    public float distance = 7.5f;
    public float height = 3.2f;
    public float lookAhead = 4f;

    [Tooltip("Higher = snappier follow.")]
    public float positionSmooth = 8f;
    public float lookSmooth = 12f;

    [Header("FOV")]
    public float baseFov = 65f;
    public float maxFov = 82f;
    public float fovSmooth = 5f;

    VehicleController vehicle;
    Vector3 currentPos;
    Vector3 currentLook;
    float currentFov;

    void Start()
    {
        currentFov = baseFov;
        if (target)
        {
            currentPos = transform.position;
            currentLook = target.position + Vector3.up * 1.2f;
            vehicle = target.GetComponent<VehicleController>();
        }
    }

    void LateUpdate()
    {
        if (target == null)
        {
            var car = FindObjectOfType<VehicleController>();
            if (car != null) { target = car.transform; Start(); }
            return;
        }
        if (vehicle == null)
            vehicle = target.GetComponent<VehicleController>();

        // Face along travel direction, blended with the car heading.
        Vector3 dir = target.forward;
        if (vehicle != null && vehicle.Velocity.sqrMagnitude > 16f)
            dir = Vector3.Slerp(target.forward, vehicle.Velocity.normalized, 0.35f);

        dir.y *= 0.4f;                       // don't tilt the camera into the sky on slopes
        if (dir.sqrMagnitude > 0.001f) dir.Normalize();
        else dir = target.forward;

        Vector3 desiredPos = target.position - dir * distance + Vector3.up * height;
        float t = 1f - Mathf.Exp(-positionSmooth * Time.deltaTime);
        currentPos = Vector3.Lerp(currentPos, desiredPos, t);
        transform.position = currentPos;

        Vector3 lookPoint = target.position + target.forward * lookAhead + Vector3.up * 1.2f;
        currentLook = Vector3.Lerp(currentLook, lookPoint, 1f - Mathf.Exp(-lookSmooth * Time.deltaTime));
        transform.rotation = Quaternion.LookRotation(currentLook - transform.position, Vector3.up);

        // FOV kick with speed + boost.
        float speed01 = vehicle != null ? Mathf.Clamp01(vehicle.SpeedKmh / 170f) : 0f;
        float boost01 = vehicle != null && vehicle.IsBoosting ? 1f : 0f;
        float targetFov = Mathf.Lerp(baseFov, maxFov, speed01 * 0.5f + boost01 * 0.5f);
        currentFov = Mathf.Lerp(currentFov, targetFov, 1f - Mathf.Exp(-fovSmooth * Time.deltaTime));
        GetComponent<Camera>().fieldOfView = currentFov;
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

/// <summary>
/// Lap-race manager. Discovers all <see cref="Checkpoint"/> components, builds a
/// route, runs a countdown, tracks lap/finish/best times and coins.
/// </summary>
public class RaceManager : MonoBehaviour
{
    public enum RaceState { Countdown, Racing, Finished }

    public static RaceManager Instance { get; private set; }

    [Header("Rules")]
    [Tooltip("How many times the route must be completed.")]
    public int totalLaps = 3;
    public float countdownSeconds = 3.5f;

    public RaceState State { get; private set; } = RaceState.Countdown;
    public float RaceTime { get; private set; }
    public float FinalTime { get; private set; }
    public float BestTime { get; private set; }
    public int Lap { get; private set; } = 1;
    public int Coins { get; private set; }
    public string Message { get; private set; } = "";
    public IReadOnlyList<Checkpoint> Route { get { return route; } }

    const string BestKey = "vehicle-game-best-time";

    readonly List<Checkpoint> route = new List<Checkpoint>();
    int routePos;
    int lapsDone;

    void Awake()
    {
        Instance = this;
        float saved = PlayerPrefs.GetFloat(BestKey, -1f);
        if (saved > 0f) BestTime = saved;
    }

    void Start()
    {
        var all = FindObjectsOfType<Checkpoint>();
        if (all.Length == 0)
        {
            Debug.LogWarning("RaceManager: no Checkpoint components found in the scene.");
            State = RaceState.Racing;
            return;
        }

        var finish = all.FirstOrDefault(c => c.IsFinish);
        if (finish == null)
        {
            finish = all.OrderBy(c => c.Order).First();
            finish.IsFinish = true;
        }
        route.AddRange(all.Where(c => c != finish).OrderBy(c => c.Order));
        route.Add(finish);

        StartCoroutine(CountdownRoutine());
    }

    void Update()
    {
        if (State == RaceState.Racing)
            RaceTime += Time.deltaTime;
    }

    IEnumerator CountdownRoutine()
    {
        State = RaceState.Countdown;
        int seconds = Mathf.Max(1, Mathf.CeilToInt(countdownSeconds));
        for (int i = seconds; i >= 1; i--)
        {
            Message = i.ToString();
            yield return new WaitForSeconds(1f);
        }
        Message = "GO!";
        State = RaceState.Racing;
        yield return new WaitForSeconds(1f);
        if (State == RaceState.Racing)
            Message = "";
    }

    /// <summary>Called by <see cref="Checkpoint"/> triggers when the car passes a gate.</summary>
    public void OnCheckpoint(Checkpoint cp)
    {
        if (State != RaceState.Racing) return;
        if (route.Count == 0 || routePos >= route.Count) return;
        if (cp != route[routePos]) return;   // skipped / wrong gate: ignore

        routePos++;
        if (!cp.IsFinish) return;

        lapsDone++;
        routePos = 0;
        if (lapsDone >= totalLaps)
            FinishRace();
        else
        {
            Lap = lapsDone + 1;
            Message = string.Format("Lap {0}/{1}", Lap, totalLaps);
        }
    }

    void FinishRace()
    {
        State = RaceState.Finished;
        FinalTime = RaceTime;
        bool newBest = BestTime <= 0f || FinalTime < BestTime;
        if (newBest)
        {
            BestTime = FinalTime;
            PlayerPrefs.SetFloat(BestKey, FinalTime);
            PlayerPrefs.Save();
        }
        Message = newBest
            ? string.Format("FINISHED  {0}  (NEW BEST!)", TimeText(FinalTime))
            : string.Format("FINISHED  {0}   best {1}", TimeText(FinalTime), TimeText(BestTime));
    }

    public void AddCoin() { Coins++; }

    /// <summary>Reset the timer/lap state and rerun the countdown.</summary>
    public void RestartRace()
    {
        StopAllCoroutines();
        RaceTime = 0f;
        FinalTime = 0f;
        routePos = 0;
        lapsDone = 0;
        Lap = 1;
        Coins = 0;
        StartCoroutine(CountdownRoutine());
    }

    public static string TimeText(float t)
    {
        if (t <= 0f) return "--:--.--";
        var ts = TimeSpan.FromSeconds(t);
        return string.Format("{0:0}:{1:00}.{2:00}", ts.Minutes, ts.Seconds, ts.Milliseconds / 10);
    }
}

using UnityEngine;

/// <summary>
/// A race gate. Attach to a GameObject with an isTrigger collider.
/// Gates are passed in ascending <see cref="Order"/>; the gate with
/// <see cref="IsFinish"/> set completes a lap.
/// </summary>
public class Checkpoint : MonoBehaviour
{
    public int Order;
    public bool IsFinish;

    void OnTriggerEnter(Collider other)
    {
        if (other.GetComponentInParent<VehicleController>() == null) return;
        if (RaceManager.Instance != null)
            RaceManager.Instance.OnCheckpoint(this);
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = IsFinish ? Color.yellow : Color.cyan;
        var col = GetComponent<Collider>();
        if (col != null)
            Gizmos.DrawWireCube(col.bounds.center, col.bounds.size);
    }
}

using UnityEngine;

/// <summary>
/// Spinning collectible. Attach to a small mesh with an isTrigger collider.
/// Picked up automatically by the vehicle; counted by the <see cref="RaceManager"/>.
/// </summary>
public class CoinCollectible : MonoBehaviour
{
    public float spinSpeed = 180f;

    void Update()
    {
        transform.Rotate(0f, spinSpeed * Time.deltaTime, 0f, Space.Self);
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.GetComponentInParent<VehicleController>() == null) return;
        if (RaceManager.Instance != null)
            RaceManager.Instance.AddCoin();
        gameObject.SetActive(false);
    }
}

using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Race HUD: speed, boost bar, timer, best time, lap and coin counters,
/// and center messages (countdown / lap / result).
/// All fields are optional; whatever is assigned gets updated.
/// </summary>
public class GameHUD : MonoBehaviour
{
    public Text speedText;
    public Text timeText;
    public Text bestText;
    public Text lapText;
    public Text coinText;
    public Text messageText;
    public Image boostFill;

    VehicleController vehicle;
    RaceManager race;
    static readonly Color BoostFull = new Color(0.4f, 0.9f, 1f);
    static readonly Color BoostLow = new Color(1f, 0.55f, 0.2f);

    void Start()
    {
        vehicle = FindObjectOfType<VehicleController>();
        race = FindObjectOfType<RaceManager>();
    }

    void LateUpdate()
    {
        if (vehicle == null) vehicle = FindObjectOfType<VehicleController>();
        if (race == null) race = FindObjectOfType<RaceManager>();

        if (vehicle != null)
        {
            if (speedText) speedText.text = Mathf.RoundToInt(vehicle.SpeedKmh) + " km/h";
            if (boostFill)
            {
                float f = Mathf.Clamp01(vehicle.Boost01);
                boostFill.rectTransform.localScale = new Vector3(f, 1f, 1f);
                boostFill.color = f < 0.25f ? BoostLow : BoostFull;
            }
        }
        else if (speedText) speedText.text = "0 km/h";

        if (race == null) return;

        if (timeText) timeText.text = RaceManager.TimeText(race.RaceTime);
        if (bestText) bestText.text = "BEST " + RaceManager.TimeText(race.BestTime);
        if (lapText) lapText.text = "LAP " + race.Lap + "/" + race.TotalLaps;
        if (coinText) coinText.text = "COINS " + race.Coins;
        if (messageText) messageText.text = race.Message;
    }
}

using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

/// <summary>
/// One-click demo track generator.
/// Menu: Tools > Vehicle Game > Build Demo Scene.
/// Creates a full playable scene: oval track, 8 gates (lap + finish), coins,
/// ramps, cones, the player car, chase camera, RaceManager and HUD, then saves it.
/// </summary>
public static class DemoSceneBuilder
{
    const float RoadRadius = 55f;   // track centerline radius
    const float RoadWidth = 14f;    // drivable width
    const float RoadTopY = 0.5f;    // top surface of the road slabs
    const int Segments = 56;        // road slab count
    const int Gates = 8;            // checkpoints (gate 0 = FINISH)
    const int Laps = 3;

    [MenuItem("Tools/Vehicle Game/Build Demo Scene")]
    public static void Build()
    {
        var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

        // ---------- Materials ----------
        var grass = Solid(new Color(0.36f, 0.60f, 0.30f));
        var asphalt = Solid(new Color(0.24f, 0.24f, 0.27f));
        var kerb = Solid(new Color(0.9f, 0.9f, 0.92f));
        var banner = Solid(new Color(0.95f, 0.75f, 0.10f));
        var bodyCol = Solid(new Color(0.85f, 0.16f, 0.16f));
        var glassCol = Solid(new Color(0.10f, 0.13f, 0.16f));
        var darkCol = Solid(new Color(0.08f, 0.08f, 0.09f));
        var rubberCol = Solid(new Color(0.10f, 0.10f, 0.11f));
        var rimCol = Solid(new Color(0.55f, 0.55f, 0.58f));
        var coinCol = Solid(new Color(1f, 0.82f, 0.15f));
        var rampCol = Solid(new Color(0.72f, 0.38f, 0.12f));
        var coneCol = Solid(new Color(1f, 0.45f, 0.05f));
        var hintUi = Solid(new Color(0.9f, 0.9f, 0.9f, 0.9f));

        // ---------- Ground ----------
        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
        ground.name = "Ground";
        ground.transform.position = Vector3.zero;
        ground.transform.localScale = Vector3.one * 30f;   // 300 x 300
        ground.GetComponent<Renderer>().sharedMaterial = grass;
        ground.isStatic = true;

        // ---------- Road (segments of an oval) ----------
        float circumference = 2f * Mathf.PI * RoadRadius;
        float segLen = circumference / Segments + 0.5f;    // slight overlap, no gaps
        for (int i = 0; i < Segments; i++)
        {
            float a = i * Mathf.PI * 2f / Segments;
            Vector3 pos = Circle(a, RoadRadius);
            pos.y = 0.25f;                                  // slab center: top at RoadTopY
            Box("Road " + i, null, pos, Vector3.zero, new Vector3(segLen, 0.5f, RoadWidth), asphalt);
        }

        // White finish strip at gate 0.
        {
            Vector3 pos = Circle(0f, RoadRadius);
            pos.y = RoadTopY + 0.02f;
            Box("FinishStrip", null, pos, Vector3.zero, new Vector3(2.5f, 0.04f, RoadWidth), kerb);
        }

        // ---------- Gates / checkpoints ----------
        for (int i = 0; i < Gates; i++)
        {
            float a = i * Mathf.PI * 2f / Gates;
            float gateHeight = i == 0 ? 8f : 7f;

            var gate = new GameObject(i == 0 ? "Gate 0 (FINISH)" : "Gate " + i);
            gate.transform.position = Circle(a, RoadRadius);
            gate.transform.position = new Vector3(gate.transform.position.x, RoadTopY, gate.transform.position.z);
            gate.transform.rotation = Quaternion.LookRotation(Tangent(a));

            Box("Pillar L", gate.transform, new Vector3(-RoadWidth * 0.5f - 0.5f, gateHeight * 0.5f, 0f),
                Vector3.zero, new Vector3(0.8f, gateHeight, 0.9f), kerb);
            Box("Pillar R", gate.transform, new Vector3(RoadWidth * 0.5f + 0.5f, gateHeight * 0.5f, 0f),
                Vector3.zero, new Vector3(0.8f, gateHeight, 0.9f), kerb);
            Box("Banner", gate.transform, new Vector3(0f, gateHeight + 0.4f, 0f),
                Vector3.zero, new Vector3(RoadWidth + 2f, 0.9f, 0.9f), i == 0 ? banner : kerb);

            int order = i;
            bool isFinish = i == 0;
            var trigger = new GameObject("GateTrigger", typeof(BoxCollider), typeof(Checkpoint));
            trigger.transform.SetParent(gate.transform, false);
            trigger.transform.localPosition = new Vector3(0f, gateHeight * 0.5f, 0f);
            var col = trigger.GetComponent<BoxCollider>();
            col.isTrigger = true;
            col.size = new Vector3(RoadWidth, gateHeight, 3.5f);
            var cp = trigger.GetComponent<Checkpoint>();
            cp.Order = order;
            cp.IsFinish = isFinish;
        }

        // ---------- Coins (3 per gate gap, centerline) ----------
        for (int i = 0; i < Gates; i++)
        {
            float gapAngle = Mathf.PI * 2f / Gates;
            for (int k = 1; k <= 3; k++)
            {
                float a = i * gapAngle + gapAngle * k / 4f;
                Vector3 pos = Circle(a, RoadRadius);
                pos.y = RoadTopY + 0.85f;
                var coin = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                coin.name = "Coin " + i + "-" + k;
                coin.transform.position = pos;
                coin.transform.localScale = new Vector3(0.9f, 0.9f, 0.2f);
                coin.GetComponent<Renderer>().sharedMaterial = coinCol;
                coin.GetComponent<SphereCollider>().isTrigger = true;
                coin.AddComponent<CoinCollectible>();
            }
        }

        // ---------- Fun zone: ramps + cones ----------
        var fun = new GameObject("FunZone");
        Box("Ramp A", fun.transform, new Vector3(0f, 0.7f, 0f), new Vector3(0f, 0f, 0f)? new Vector3() : new Vector3(), 
            Vector3.zero, rampCol); // placeholder removed below
        DestroyImmediatePlaceholderRamps(fun);

        Box("Ramp A", fun.transform, new Vector3(-6f, 0.8f, 6f), new Vector3(-16f, 25f, 0f),
            new Vector3(9f, 0.6f, 7f), rampCol);
        Box("Ramp B", fun.transform, new Vector3(10f, 0.8f, -2f), new Vector3(-16f, -110f, 0f),
            new Vector3(9f, 0.6f, 7f), rampCol);

        for (int i = 0; i < 6; i++)
        {
            float a = Mathf.PI * 2f * i / 6f + 0.3f;
            Vector3 pos = Circle(a, RoadRadius - (RoadWidth * 0.5f - 1.6f));
            pos.y = RoadTopY + 0.55f;
            Box("Cone " + i, null, pos, Vector3.zero, new Vector3(0.7f, 1.1f, 0.7f), coneCol);
        }
        Object.DestroyImmediate(FindChildByName(fun, "Ramp A (placeholder)"));

        // ---------- Player car ----------
        var car = new GameObject("Player", typeof(Rigidbody), typeof(VehicleController), typeof(BoxCollider));
        float spawnA = 0.045f;   // just past the finish line, behind gate 1
        car.transform.position = Circle(spawnA, RoadRadius);
        car.transform.position = new Vector3(car.transform.position.x, RoadTopY, car.transform.position.z);
        car.transform.rotation = Quaternion.LookRotation(Tangent(spawnA));

        var carBody = Box("Body", car.transform, new Vector3(0f, 0.75f, 0f), Vector3.zero,
            new Vector3(2.05f, 0.85f, 4.5f), bodyCol);
        carBody.name = "Body";
        Box("Cabin", car.transform, new Vector3(0f, 1.38f, -0.35f), Vector3.zero,
            new Vector3(1.65f, 0.6f, 1.9f), glassCol);
        Box("Spoiler", car.transform, new Vector3(0f, 1.32f, -2.25f), Vector3.zero,
            new Vector3(2.1f, 0.12f, 0.55f), darkCol);

        var boxCol = car.GetComponent<BoxCollider>();
        boxCol.center = new Vector3(0f, 0.9f, 0f);
        boxCol.size = new Vector3(2.0f, 1.8f, 4.4f);

        var wheelsParent = new GameObject("Wheels");
        wheelsParent.transform.SetParent(car.transform, false);
        var front = new List<Transform>();
        var rear = new List<Transform>();
        AddWheel(wheelsParent.transform, "Wheel FL", new Vector3(-0.98f, 0.34f, 1.45f), rubberCol, rimCol, front);
        AddWheel(wheelsParent.transform, "Wheel FR", new Vector3(0.98f, 0.34f, 1.45f), rubberCol, rimCol, front);
        AddWheel(wheelsParent.transform, "Wheel RL", new Vector3(-0.98f, 0.34f, -1.45f), rubberCol, rimCol, rear);
        AddWheel(wheelsParent.transform, "Wheel RR", new Vector3(0.98f, 0.34f, -1.45f), rubberCol, rimCol, rear);

        var controller = car.GetComponent<VehicleController>();
        controller.frontWheels = front.ToArray();
        controller.rearWheels = rear.ToArray();
        controller.maxSpeed = 120f;
        controller.boostMaxSpeed = 170f;

        var rb2 = car.GetComponent<Rigidbody>();
        rb2.mass = 1200f;

        // ---------- Camera ----------
        Camera cam = Camera.main;
        if (cam == null) cam = Object.FindObjectOfType<Camera>();
        if (cam != null)
        {
            cam.transform.position = car.transform.position - car.transform.forward * 7.5f + Vector3.up * 3.2f;
            cam.transform.rotation = Quaternion.LookRotation(car.transform.position - cam.transform.position);
            var follow = cam.gameObject.AddComponent<CameraFollow>();
            follow.target = car.transform;
            follow.baseFov = 65f;
            follow.maxFov = 82f;
        }

        // ---------- Race manager ----------
        var race = new GameObject("RaceManager", typeof(RaceManager));
        race.GetComponent<RaceManager>().totalLaps = Laps;

        // ---------- HUD ----------
        BuildHud(controller, hintUi? new Color(): Color.white);

        // ---------- Save + build settings ----------
        if (!AssetDatabase.IsValidFolder("Assets/Scenes"))
            AssetDatabase.CreateFolder("Assets", "Scenes");
        const string scenePath = "Assets/Scenes/Vehicle Demo.unity";
        EditorSceneManager.SaveScene(scene, scenePath);

        var list = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
        if (!list.Exists(s => s.path == scenePath))
        {
            list.Add(new EditorBuildSettingsScene(scenePath, true));
            EditorBuildSettings.scenes = list.ToArray();
        }

        Debug.Log("Vehicle demo scene created at " + scenePath + " — press Play to drive!");
    }

    static void BuildHud(VehicleController _, Color hintColor)
