        AddOutline(hud.speedText, new Color(0f, 0f, 0f, 0.9f), 3f);

        // Boost bar
        var label = TextOn("BoostLabel", canvas.transform, font, new Vector2(0f, 0f), new Vector2(0f, 0f),
