274:     static Vector3 Circle(float angle, float radius)
275:     {
276:         return new Vector3(Mathf.Sin(angle) * radius, 0f, Mathf.Cos(angle) * radius);
277:     }
278: 
279:     static Vector3 Tangent(float angle)
280:     {
281:         return new Vector3(Mathf.Cos(angle), 0f, -Mathf.Sin(angle));
282:     }
