284:     static GameObject Box(string name, Transform parent, Vector3 localPos, Vector3 localRot, Vector3 scale, Material mat)
285:     {
286:         var go = GameObject.CreatePrimitive(PrimitiveType.Cube);
287:         go.name = name;
288:         if (parent != null) go.transform.SetParent(parent, false);
289:         go.transform.localPosition = localPos;
290:         if (localRot != Vector3.zero) go.transform.localRotation = Quaternion.Euler(localRot);
291:         go.transform.localScale = scale;
292:         go.GetComponent<Renderer>().sharedMaterial = mat;
293:         return go;
294:     }
295: 
296:     static void AddWheel(Transform parent, string name, Vector3 localPos, Material rubber, Material rim, List<Transform> list)
297:     {
298:         var wheel = new GameObject(name);
299:         wheel.transform.SetParent(parent, false);
300:         wheel.transform.localPosition = localPos;
301:         wheel.transform.localRotation = Quaternion.Euler(0f, 0f, 90f);   // cylinder axis -> X
302: 
303:         var tire = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
304:         tire.name = "Tire";
305:         Object.DestroyImmediate(tire.GetComponent<Collider>());
306:         tire.transform.SetParent(wheel.transform, false);
307:         tire.transform.localScale = new Vector3(0.68f, 0.22f, 0.68f);
308:         tire.GetComponent<Renderer>().sharedMaterial = rubber;
309: 
310:         var hub = GameObject.CreatePrimitive(PrimitiveType.Sphere);
311:         hub.name = "Hub";
312:         Object.DestroyImmediate(hub.GetComponent<Collider>());
313:         hub.transform.SetParent(wheel.transform, false);
314:         hub.transform.localScale = new Vector3(0.4f, 0.42f, 0.4f);
315:         hub.GetComponent<Renderer>().sharedMaterial = rim;
316: 
317:         list.Add(wheel.transform);
318:     }
319: 
320:     static GameObject ImageOn(string name, Transform parent, Vector2 anchor, Vector2 pivot,
321:         Vector2 pos, Vector2 size, Color color)
322:     {
323:         var go = new GameObject(name, typeof(RectTransform), typeof(Image));
324:         go.transform.SetParent(parent, false);
325:         var rt = go.GetComponent<RectTransform>();
326:         SetRect(rt, anchor, pivot, pos, size);
327:         go.GetComponent<Image>().color = color;
328:         go.GetComponent<Image>().raycastTarget = false;
329:         return go;
330:     }
331: 
332:     static Text TextOn(string name, Transform parent, Font font, Vector2 anchor, Vector2 pivot,
333:         Vector2 pos, Vector2 size, float fontSize, TextAnchor align, Color color)
334:     {
335:         var go = new GameObject(name, typeof(RectTransform));
336:         go.transform.SetParent(parent, false);
337:         SetRect(go.GetComponent<RectTransform>(), anchor, pivot, pos, size);
338:         var t = go.AddComponent<Text>();
339:         if (font != null) t.font = font;
340:         t.fontSize = (int)fontSize;
341:         t.alignment = align;
342:         t.color = color;
343:         t.horizontalOverflow = HorizontalWrapMode.Overflow;
344:         t.verticalOverflow = VerticalWrapMode.Overflow;
345:         t.raycastTarget = false;
346:         return t;
347:     }
348: 
349:     static void SetRect(RectTransform rt, Vector2 anchor, Vector2 pivot, Vector2 pos, Vector2 size)
350:     {
351:         rt.anchorMin = anchor;
352:         rt.anchorMax = anchor;
353:         rt.pivot = pivot;
354:         rt.anchoredPosition = pos;
355:         rt.sizeDelta = size;
356:     }
357: 
358:     static void AddOutline(Graphic graphic, Color color, float thickness)
359:     {
360:         if (graphic == null) return;
361:         var outline = graphic.gameObject.AddComponent<Outline>();
362:         outline.effectColor = color;
363:         outline.effectDistance = new Vector2(thickness, thickness);
364:     }
365: 
366:     static Font DefaultFont()
367:     {
368:         string[] names = { "LegacyRuntime.ttf", "Arial.ttf" };
369:         foreach (string n in names)
370:         {
371:             try
372:             {
373:                 var f = Resources.GetBuiltinResource<Font>(n);
374:                 if (f != null) return f;
375:             }
376:             catch { /* try next */ }
377:         }
378:         return null;
379:     }
380: 
381:     static Material Solid(Color c)
382:     {
383:         Shader shader = Shader.Find("Standard");
384:         if (shader == null) shader = Shader.Find("Universal Render Pipeline/Lit");
385:         if (shader == null) shader = Shader.Find("Unlit/Color");
386:         if (shader == null) shader = Shader.Find("Sprites/Default");
387:         var m = new Material(shader);
388:         if (m.HasProperty("_Color")) m.color = c;
389:         else if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
390:         return m;
391:     }
392: }

